import test from'node:test';import assert from'node:assert/strict';import{make,validate,apply}from'./state.js';import{portable,parse}from'../creative-kit/state.js';
test('borrowing preserves all three answers and captures the source strength',()=>{const w=make(),original=structuredClone(w.answers.a);apply(w,{type:'borrow',from:'a',to:'q'});assert.deepEqual(w.answers.a,original);assert.equal(w.answers.q.borrowed[0].text,original.strength);apply(w,{type:'edit',collection:'answers',item:'a',field:'strength',value:'New strength'});assert.equal(w.answers.q.borrowed[0].stale,true);assert.equal(w.answers.q.borrowed[0].text,original.strength);});
test('selecting a test keeps other mechanisms and exports their unresolved costs',()=>{const w=make();apply(w,{type:'choose',id:'q'});assert.equal(Object.keys(w.answers).length,3);assert.deepEqual(parse(portable(w,'answers',validate),'answers',validate),w);assert.throws(()=>apply(w,{type:'borrow',from:'a',to:'a'}));});
